algorithm GradeClassification
    define grade as integer;
    read grade;
    if grade >= 9 then
        write 4;
    else
        if grade >= 7 then
            write 3;
        else
            if grade >= 5 then
                write 2;
            else
                write 1;
            endIf
        endIf
    endIf
endAlgorithm
